import{_ as e,o,c as d,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"International Tax & Withholding — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"International Tax & Withholding — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/international-tax-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"International Tax & Withholding — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/international-tax-production-readiness"}]]},"headers":[],"relativePath":"deployment/international-tax-production-readiness.md","filePath":"deployment/international-tax-production-readiness.md","lastUpdated":1788177646000}'),a={name:"deployment/international-tax-production-readiness.md"};function r(i,t,s,l,c,g){return o(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="international-tax-withholding-—-production-readiness-audit" tabindex="-1">International Tax &amp; Withholding — Production Readiness Audit <a class="header-anchor" href="#international-tax-withholding-—-production-readiness-audit" aria-label="Permalink to &quot;International Tax &amp; Withholding — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-08-24</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — staging → production after CI, migrate, and smoke</td></tr><tr><td><strong>Scope</strong></td><td>Accounting <strong>1.7.0 → 1.7.2</strong> — tax types catalog, billing line tax types, payment/expense withholding</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/international-tax-withholding</code></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/tax-types">User guide</a> · <a href="/developer-guide/tax-types">Developer</a> · <a href="/api/tenant-v1-tax-types">API</a></td></tr></tbody></table><p>Additive work on the existing Accounting module. No new permission slugs (reuses <code>accounting.*</code>). No new env vars or queues. Migrate-only deploy path.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Workspaces that already entitled <strong>Accounting</strong> pick up tax types and withholding after migrate. Catalog bumps do <strong>not</strong> auto-install for workspaces that never entitled the module. <strong>Invoices</strong>, <strong>Payments</strong>, and <strong>Expenses</strong> modules unlock the full billing and WHT surface.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td><code>module:accounting</code> + <code>accounting.*</code> (no new family)</td><td><strong>Pass</strong></td></tr><tr><td>Tax types CRUD + tenant isolation</td><td><strong>Pass</strong></td></tr><tr><td>Invoice/credit accrual GL split (Dr AR / Cr Revenue / Cr Tax Payable)</td><td><strong>Pass</strong></td></tr><tr><td>Payment WHT 3-line journal (Dr Deposit net / Dr WHT Receivable / Cr AR gross)</td><td><strong>Pass</strong></td></tr><tr><td>Expense pay WHT 3-line journal</td><td><strong>Pass</strong></td></tr><tr><td>List API <code>direction</code> sort vs filter collision (P0)</td><td><strong>Fixed</strong> (1.7.2)</td></tr><tr><td>Sort column whitelist on tax types list</td><td><strong>Pass</strong></td></tr><tr><td>Payment &amp; expense view pages show withholding</td><td><strong>Pass</strong></td></tr><tr><td>Pest tax/WHT/accounting</td><td><strong>Pass</strong> (14+)</td></tr><tr><td>Playwright <code>test:e2e:accounting</code></td><td><strong>Pass</strong> (8 runnable, 2 authz skips on entitled demo)</td></tr><tr><td>Docs + changelog + this runbook</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI green, <code>php artisan migrate --force</code>, and staging smoke below.</p><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>F1</td><td><strong>Critical</strong></td><td><strong>Fixed</strong></td><td>Tax types list returned empty when UI sent <code>direction=asc|desc</code> (treated as tax direction filter)</td><td>Only filter when value is a tax direction enum; use <code>sort</code> + <code>direction</code> for ordering; Pest regression</td></tr><tr><td>F2</td><td>Medium</td><td><strong>Fixed</strong></td><td>Payment view did not show posted withholding amount</td><td>Read-only WHT fields on payment view; API loads <code>withholdingTaxType</code></td></tr><tr><td>F3</td><td>Low</td><td><strong>Fixed</strong></td><td>Expense view did not show withholding after pay</td><td>Same pattern on expense view</td></tr><tr><td>F4</td><td>Low</td><td><strong>Fixed</strong></td><td><code>orderBy($request-&gt;input(&#39;sort&#39;))</code> without whitelist</td><td>Allowed sorts: <code>name</code>, <code>code</code>, <code>kind</code>, <code>direction</code>, <code>rate</code>, <code>created_at</code>, <code>updated_at</code></td></tr><tr><td>F5</td><td>Low</td><td><strong>Fixed</strong></td><td>Select controlled/uncontrolled warnings on tax type form</td><td>Stable <code>watch()</code> values; client-side zod for required GL accounts</td></tr><tr><td>F6</td><td>Info</td><td><strong>Accepted</strong></td><td>Authz e2e skips when demo workspace has Accounting</td><td>Run negative authz on isolated tenant in CI if needed</td></tr></tbody></table><h3 id="accepted-intentional" tabindex="-1">Accepted / intentional <a class="header-anchor" href="#accepted-intentional" aria-label="Permalink to &quot;Accepted / intentional&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>No new permissions</td><td>Reuse existing <code>accounting.*</code> for tax types</td></tr><tr><td>Payment <code>amount</code> = gross applied to AR</td><td>Withholding reduces deposit only</td></tr><tr><td>Jurisdiction-agnostic catalog</td><td>FBR-style values are example <code>authority_reference</code> only</td></tr><tr><td>Deferred</td><td>Country templates, WHT certificates, payroll statutory — out of scope</td></tr></tbody></table><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/Accounting/TaxTypeTest.php</code></td><td><strong>Pass</strong></td><td>CRUD, list sort/filter, invalid sort fallback, authz, soft delete</td></tr><tr><td><code>PaymentWithholdingTest</code>, <code>ExpenseWithholdingTest</code></td><td><strong>Pass</strong></td><td>3-line journals</td></tr><tr><td><code>CustomerInvoiceAccountingTest</code>, <code>CustomerCreditNoteAccountingTest</code></td><td><strong>Pass</strong></td><td>Tax split to <code>2100</code></td></tr><tr><td><code>npm run test:e2e:accounting</code></td><td><strong>8 passed, 2 skipped</strong></td><td>Tax types 4/4 in one session; authz skips on entitled demo</td></tr></tbody></table><p><strong>Tax types e2e (single session):</strong> validation + CRUD; invoice tax split; payment WHT create/post + view; expense pay WHT + view.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> — <code>composer install</code> then <code>php artisan migrate --force</code> (tax_types, billing line FK, WHT columns, catalog <strong>1.7.0 → 1.7.2</strong>)</li><li><strong>SPA</strong> — tax types pages, billing line picker, payment/expense WHT UI, view-page withholding</li><li><strong>Docs</strong> — user/dev/API/changelog + this page</li><li>Staging smoke below before production traffic</li></ol><p>Suggested merge: <strong>Backend → Frontend → Docs</strong>. Do <strong>not</strong> <code>db:seed</code> in production.</p><p>Starter GL accounts <strong>1150</strong> (WHT receivable) and <strong>2150</strong> (WHT payable) are created via the existing chart seeder when Accounting is enabled or CoA is seeded.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations applied (tax_types + WHT columns + catalog bumps through <strong>1.7.2</strong>)</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Catalog <code>accounting</code> version <strong>1.7.2</strong></td><td>Ops</td><td>☐</td></tr><tr><td>3</td><td>Pest tax/WHT/accounting green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>4</td><td>Playwright <code>test:e2e:accounting</code> green</td><td>QA</td><td>☐</td></tr><tr><td>5</td><td>Staging smoke signed off</td><td>QA / Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → Accounting already installed (or install free)</li><li><strong>Tax types</strong> → list shows rows (not empty) → create sales tax + payment-in WHT</li><li><strong>Invoice</strong> → line with tax type → send → journal splits tax to <strong>2100</strong></li><li><strong>Payment</strong> → gross amount + WHT type → post → view shows <strong>Withheld</strong> and <strong>Deposit (net)</strong></li><li><strong>Expense</strong> → approve → pay with WHT → view shows <strong>Withheld</strong> and <strong>Cash paid (net)</strong></li><li>Contact/vendor default withholding type pre-fills payment/expense pay dialogs</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend</td><td>Redeploy previous SPA (WHT UI disappears; API columns remain)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; keep additive migrations</td></tr><tr><td>Module disable</td><td>Marketplace uninstall Accounting (tax type rows retained)</td></tr><tr><td>Schema</td><td>Do <strong>not</strong> roll back tax_types / WHT columns in prod without a data plan</td></tr></tbody></table><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Spatie activity log names: <code>tax_types</code>, <code>customer_payments</code>, <code>expenses</code></li><li>Nightwatch: validation errors on <code>POST …/payments/{id}/post</code> and <code>POST …/expenses/{id}/pay</code> with WHT fields</li><li>Support signal: empty tax types list after deploy → verify Backend <strong>1.7.2</strong> list fix is deployed</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Name</th><th>Date</th><th>Decision</th></tr></thead><tbody><tr><td>Engineering</td><td></td><td></td><td><strong>Go</strong> / No-Go</td></tr><tr><td>Product</td><td></td><td></td><td>F1–F5 fixed</td></tr><tr><td>Ops</td><td></td><td></td><td>Staging migrate + smoke ☐</td></tr></tbody></table><p><strong>Recommendation:</strong> Merge companions after CI green; run staging smoke.</p>',38)])])}const u=e(a,[["render",r]]);export{p as __pageData,u as default};
